package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var trRec TaxRec

var taxFileScanner *bufio.Scanner
var taxFile *os.File

func pow10(n int) decimal.Decimal {
	return decimal.NewFromInt(1).Shift(int32(n))
}

func storeField(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate toward zero to scale (COBOL without ROUNDED truncates, with ROUNDED caller rounds)
	// This function expects val already at desired scale handling.
	// Enforce picture overflow: keep low-order digits
	// Value is represented; we need to keep only intDigits integer digits + scale fractional
	// Implemented as modulo 10^(intDigits+scale) on the scaled integer.
	if intDigits < 0 {
		return val.Truncate(scale)
	}
	v := val.Truncate(scale)
	// work with scaled integer
	scaled := v.Shift(scale) // integer value
	// modulus = 10^(intDigits+scale)
	mod := pow10(intDigits + int(scale))
	// For negative numbers, COBOL keeps sign? Keep simple: truncate magnitude
	neg := scaled.IsNegative()
	if neg {
		scaled = scaled.Abs()
	}
	// low-order digits
	// scaled % mod
	// decimal does not have mod for large, use DivMod via Int part
	// Use decimal.Mod if available? shopspring has Mod
	low := scaled.Mod(mod)
	if neg {
		low = low.Neg()
	}
	return low.Shift(-scale)
}

func roundAndStore(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	r := val.Round(scale)
	return storeField(r, intDigits, scale)
}
func truncateAndStore(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := val.Truncate(scale)
	return storeField(t, intDigits, scale)
}

// edited formatting
func formatEdited(val decimal.Decimal, picture string) string {
	// picture like "ZZZ,ZZ9.99" or "ZZ,ZZZ,ZZ9.99"
	dotIdx := strings.Index(picture, ".")
	var intPic string
	var fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	// work with absolute value (all values positive here)
	neg := val.IsNegative()
	if neg {
		val = val.Abs()
	}
	// integer part with high-order truncation
	intPart := val.Truncate(0).Abs()
	// low-order digits only
	if intSlots > 0 {
		mod := pow10(intSlots)
		// intPart % mod
		intPart = intPart.Mod(mod)
	}
	// integer digits string zero padded to intSlots
	intStr := intPart.String() // no decimal
	// String() may be like "0" ; ensure we handle
	// intPart is truncated integer, so string is integer
	// Pad
	if len(intStr) > intSlots {
		// overflow already modded, but just in case
		intStr = intStr[len(intStr)-intSlots:]
	}
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}
	// Build integer formatted array
	intPicChars := []rune(intPic)
	intFormatted := make([]rune, len(intPicChars))
	digitIdx := 0
	// map placeholder to digit char
	for i, ch := range intPicChars {
		if ch == 'Z' || ch == '9' {
			intFormatted[i] = rune(intStr[digitIdx])
			digitIdx++
		} else {
			// comma
			intFormatted[i] = ch
		}
	}
	// Determine first non-zero in intStr
	firstNZ := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNZ = i
			break
		}
	}
	if firstNZ == -1 {
		// value zero
		digitIdx = 0
		for i, pch := range intPicChars {
			if pch == 'Z' || pch == '9' {
				if pch == 'Z' {
					intFormatted[i] = ' '
				} else {
					// keep '0'
				}
				digitIdx++
			}
		}
		// commas to space if left part all spaces
		for i, pch := range intPicChars {
			if pch == ',' {
				allSpace := true
				for j := 0; j < i; j++ {
					if intPicChars[j] == 'Z' || intPicChars[j] == '9' {
						if intFormatted[j] != ' ' {
							allSpace = false
							break
						}
					} else {
						if intFormatted[j] != ' ' && intFormatted[j] != ',' {
							allSpace = false
							break
						}
					}
				}
				// if all left placeholders are spaces, comma is space
				leftHasDigit := false
				for j := 0; j < i; j++ {
					if intPicChars[j] == 'Z' || intPicChars[j] == '9' {
						if intFormatted[j] != ' ' {
							leftHasDigit = true
							break
						}
					}
				}
				if !leftHasDigit {
					intFormatted[i] = ' '
				} else {
					_ = allSpace
				}
			}
		}
	} else {
		// suppress leading zeros for Z positions before firstNZ
		digitIdx = 0
		for i, pch := range intPicChars {
			if pch == 'Z' || pch == '9' {
				if pch == 'Z' && digitIdx < firstNZ {
					intFormatted[i] = ' '
				}
				digitIdx++
			}
		}
		// commas: if every placeholder left of comma is space, comma becomes space
		for i, pch := range intPicChars {
			if pch == ',' {
				leftHasDigit := false
				for j := 0; j < i; j++ {
					if intPicChars[j] == 'Z' || intPicChars[j] == '9' {
						if intFormatted[j] != ' ' {
							leftHasDigit = true
							break
						}
					}
				}
				if !leftHasDigit {
					intFormatted[i] = ' '
				}
			}
		}
	}
	intPartStr := string(intFormatted)
	// fractional part
	fracStr := ""
	if fracDigits > 0 {
		// get fractional digits truncated/padded
		// val absolute
		// fractional = (val - trunc) * 10^fracDigits
		fracVal := val.Sub(val.Truncate(0)).Abs()
		scaledFrac := fracVal.Shift(int32(fracDigits)).Truncate(0)
		// because of decimal representation, ensure zero padded
		s := scaledFrac.String()
		// scaledFrac is integer < 10^fracDigits
		if len(s) < fracDigits {
			s = strings.Repeat("0", fracDigits-len(s)) + s
		}
		if len(s) > fracDigits {
			s = s[len(s)-fracDigits:]
		}
		fracStr = s
	}
	if dotIdx >= 0 {
		return intPartStr + "." + fracStr
	}
	return intPartStr
}

func formatCount(cnt int64, digits int) string {
	s := fmt.Sprintf("%d", cnt)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func readPara() {
	if taxFileScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if taxFileScanner.Scan() {
		line := taxFileScanner.Text()
		// COBOL LINE SEQUENTIAL: pad with spaces on right to record length 13
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		// parse
		trRec.TrId = line[0:5]
		sInc := line[5:13]
		trimmed := strings.TrimSpace(sInc)
		if trimmed == "" {
			trRec.TrIncome = decimal.NewFromInt(0)
		} else {
			// digits only; may contain leading zeros
			// parse as integer
			// remove any spaces inside? Should be digits
			d := decimal.RequireFromString(trimmed)
			// digits represent value with 2 decimal places implied
			trRec.TrIncome = d.Shift(-2)
		}
	} else {
		WsEofFlag = "Y"
	}
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func processPara() {
	tenThousand := decimal.NewFromInt(10000)
	fortyThousand := decimal.NewFromInt(40000)
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)
	rate10 := decimal.RequireFromString("0.10")
	rate20 := decimal.RequireFromString("0.20")
	rate30 := decimal.RequireFromString("0.30")

	if trRec.TrIncome.LessThanOrEqual(tenThousand) {
		v := trRec.TrIncome.Mul(rate10)
		WsTax = roundAndStore(v, 7, 2)
	} else {
		if trRec.TrIncome.LessThanOrEqual(fortyThousand) {
			diff := trRec.TrIncome.Sub(tenThousand)
			v := diff.Mul(rate20).Add(thousand)
			WsTax = roundAndStore(v, 7, 2)
		} else {
			diff := trRec.TrIncome.Sub(fortyThousand)
			v := diff.Mul(rate30).Add(sevenThousand)
			WsTax = roundAndStore(v, 7, 2)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (truncated)
	netVal := trRec.TrIncome.Sub(WsTax)
	WsNet = truncateAndStore(netVal, 7, 2)

	// ADD WS-TAX TO WS-TOTAL-TAX
	WsTotalTax = truncateAndStore(WsTotalTax.Add(WsTax), 9, 2)

	WsCount++

	WsIncEd = formatEdited(trRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s %s\n", trRec.TrId, WsIncEd, WsTaxEd, WsNetEd)

	readPara()
}

func mainPara() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		WsEofFlag = "Y"
	} else {
		defer taxFile.Close()
		taxFileScanner = bufio.NewScanner(taxFile)
		// allow long lines
	}
	readPara()
	for !isInputDone() {
		processPara()
	}
	if taxFile != nil {
		taxFile.Close()
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	cntStr := formatCount(WsCount, 3)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", cntStr, WsTotalEd)
}

func main() {
	mainPara()
}
